#!/usr/bin/env node
// Vendor KaTeX into the default theme so that a page never reaches a CDN for
// math. The output is committed; run this by hand after an upgrade of the
// katex devDependency:
//
//   node packages/cli/scripts/vendor-katex.mjs
//
// themes/default/math.js is the banner, dist/katex.min.js, the copy handler and
// scripts/math-runtime.js in that order. themes/default/math.css is the banner,
// dist/katex.min.css with every @font-face cut down to its woff2 file, and
// scripts/math-runtime.css. themes/default/fonts/katex holds the woff2 files
// and the KaTeX licence. A second run writes the same bytes.
import { copyFile, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const pkgDir = path.resolve(here, '..');
const repo = path.resolve(pkgDir, '..', '..');
const themeDir = path.join(repo, 'themes', 'default');
const katexDir = path.dirname(createRequire(path.join(pkgDir, 'package.json')).resolve('katex/package.json'));

const SOURCE = 'https://github.com/KaTeX/KaTeX';
const WOFF2 = /url\(fonts\/([^)]+\.woff2)\)\s*format\("woff2"\)/;
const FACE = /@font-face\{[^}]*\}/g;
const SRC = /src:[^;}]*/;

function banner(version, lines) {
  const head = ` * KaTeX ${version}, MIT licence, ${SOURCE}`;
  const body = lines.map((line) => (line === '' ? ' *' : ` * ${line}`));
  return ['/*', head, ' *', ...body, ' */'].join('\n');
}

function withoutSourceMap(text) {
  return text.replace(/^\/\/# sourceMappingURL=.*\r?\n?/gm, '');
}

async function writeMathJs(version) {
  const parts = [
    banner(version, [
      'Vendored by packages/cli/scripts/vendor-katex.mjs from the katex package:',
      'dist/katex.min.js, dist/contrib/copy-tex.min.js and',
      'scripts/math-runtime.js, in that order. The copy handler turns a copied',
      'equation back into the LaTeX behind it.',
      '',
      'Do not edit this file by hand; run the script after an upgrade.',
    ]),
    withoutSourceMap(await readFile(path.join(katexDir, 'dist', 'katex.min.js'), 'utf8')),
    withoutSourceMap(await readFile(path.join(katexDir, 'dist', 'contrib', 'copy-tex.min.js'), 'utf8')),
    await readFile(path.join(pkgDir, 'scripts', 'math-runtime.js'), 'utf8'),
  ];
  await writeFile(path.join(themeDir, 'math.js'), `${parts.map((part) => part.trimEnd()).join('\n')}\n`);
}

// One file per face is enough: every browser that runs KaTeX reads woff2, and
// keeping woff and ttf as well would put fifty more font files in the artifact.
function reduceFonts(css) {
  const out = css.replace(FACE, (face) =>
    face.replace(SRC, (declaration) => {
      const found = WOFF2.exec(declaration);
      if (found === null) throw new Error(`cannot find the woff2 font in: ${declaration}`);
      return `src:url(fonts/katex/${found[1]}) format("woff2")`;
    }),
  );
  if (/\.woff\)|\.ttf\)/.test(out)) throw new Error('a woff or ttf url is left in dist/katex.min.css');
  return out;
}

async function writeMathCss(version) {
  const parts = [
    banner(version, [
      'Vendored by packages/cli/scripts/vendor-katex.mjs from the katex package:',
      'dist/katex.min.css with every @font-face cut down to its woff2 file under',
      'fonts/katex/, then scripts/math-runtime.css.',
      '',
      'Do not edit this file by hand; run the script after an upgrade.',
    ]),
    reduceFonts(await readFile(path.join(katexDir, 'dist', 'katex.min.css'), 'utf8')),
    await readFile(path.join(pkgDir, 'scripts', 'math-runtime.css'), 'utf8'),
  ];
  await writeFile(path.join(themeDir, 'math.css'), `${parts.map((part) => part.trimEnd()).join('\n')}\n`);
}

async function writeFonts() {
  const from = path.join(katexDir, 'dist', 'fonts');
  const to = path.join(themeDir, 'fonts', 'katex');
  const names = (await readdir(from)).filter((name) => name.endsWith('.woff2')).sort();
  await rm(to, { recursive: true, force: true });
  await mkdir(to, { recursive: true });
  for (const name of names) await copyFile(path.join(from, name), path.join(to, name));
  await copyFile(path.join(katexDir, 'LICENSE'), path.join(to, 'LICENSE'));
  return names.length;
}

async function main() {
  const pkg = JSON.parse(await readFile(path.join(katexDir, 'package.json'), 'utf8'));
  await writeMathJs(pkg.version);
  await writeMathCss(pkg.version);
  const fonts = await writeFonts();
  process.stdout.write(`vendor-katex: KaTeX ${pkg.version}, ${fonts} woff2 fonts in themes/default/fonts/katex\n`);
}

main().catch((err) => {
  process.stderr.write(`vendor-katex: ${err instanceof Error ? err.message : String(err)}\n`);
  process.exit(1);
});
